CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (user_id, full_name)
  VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', ''));
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public

CREATE OR REPLACE FUNCTION public.enqueue_email(queue_name TEXT, payload JSONB)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN pgmq.send(queue_name, payload);
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN pgmq.send(queue_name, payload);
END;
$$

CREATE OR REPLACE FUNCTION public.read_email_batch(queue_name TEXT, batch_size INT, vt INT)
RETURNS TABLE(msg_id BIGINT, read_ct INT, message JSONB) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN;
END;
$$

CREATE OR REPLACE FUNCTION public.delete_email(queue_name TEXT, message_id BIGINT)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN pgmq.delete(queue_name, message_id);
EXCEPTION WHEN undefined_table THEN
  RETURN FALSE;
END;
$$

CREATE OR REPLACE FUNCTION public.move_to_dlq(source_queue TEXT, dlq_name TEXT, message_id BIGINT, payload JSONB)
RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN PERFORM pgmq.create(dlq_name); EXCEPTION WHEN OTHERS THEN NULL; END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN PERFORM pgmq.delete(source_queue, message_id); EXCEPTION WHEN undefined_table THEN NULL; END;
  RETURN new_id;
END;
$$

CREATE OR REPLACE FUNCTION public.check_and_issue_certificate()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_subject_id uuid; v_total_lessons int; v_completed_lessons int;
BEGIN
  IF NEW.completed IS NOT TRUE THEN RETURN NEW; END IF;
  SELECT subject_id INTO v_subject_id FROM public.lessons WHERE id = NEW.lesson_id;
  IF v_subject_id IS NULL THEN RETURN NEW; END IF;
  SELECT count(*) INTO v_total_lessons FROM public.lessons WHERE subject_id = v_subject_id;
  SELECT count(*) INTO v_completed_lessons FROM public.user_progress up
    JOIN public.lessons l ON l.id = up.lesson_id
    WHERE up.user_id = NEW.user_id AND l.subject_id = v_subject_id AND up.completed = true;
  IF v_completed_lessons >= v_total_lessons AND v_total_lessons > 0 THEN
    INSERT INTO public.certificates (user_id, subject_id) VALUES (NEW.user_id, v_subject_id) ON CONFLICT (user_id, subject_id) DO NOTHING;
    INSERT INTO public.notifications (user_id, title, message, type) VALUES (NEW.user_id, 'شهادة إتمام جديدة 🎓', 'تهانينا! لقد أكملت جميع دروس المادة وحصلت على شهادة إتمام.', 'success');
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.generate_referral_code()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
  IF NEW.referral_code IS NULL THEN
    NEW.referral_code := upper(substr(md5(NEW.user_id::text || now()::text), 1, 8));
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.award_points_on_progress()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE v_points integer; v_badge record; v_lessons_completed integer; v_total_points integer; v_certificates integer;
BEGIN
  IF NEW.completed IS NOT TRUE THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM student_points WHERE user_id = NEW.user_id AND reason = 'lesson_completed' AND reference_id = NEW.lesson_id) THEN RETURN NEW; END IF;
  v_points := 10;
  IF NEW.quiz_score IS NOT NULL AND NEW.quiz_score >= 80 THEN v_points := v_points + 5; END IF;
  INSERT INTO student_points (user_id, points, reason, reference_id) VALUES (NEW.user_id, v_points, 'lesson_completed', NEW.lesson_id);
  SELECT count(*) INTO v_lessons_completed FROM user_progress WHERE user_id = NEW.user_id AND completed = true;
  SELECT COALESCE(SUM(points), 0) INTO v_total_points FROM student_points WHERE user_id = NEW.user_id;
  SELECT count(*) INTO v_certificates FROM certificates WHERE user_id = NEW.user_id;
  FOR v_badge IN SELECT * FROM badges LOOP
    IF EXISTS (SELECT 1 FROM student_badges WHERE user_id = NEW.user_id AND badge_id = v_badge.id) THEN CONTINUE; END IF;
    IF (v_badge.condition_type = 'lessons_completed' AND v_lessons_completed >= v_badge.condition_value)
    OR (v_badge.condition_type = 'points_earned' AND v_total_points >= v_badge.condition_value)
    OR (v_badge.condition_type = 'certificates_earned' AND v_certificates >= v_badge.condition_value)
    THEN
      INSERT INTO student_badges (user_id, badge_id) VALUES (NEW.user_id, v_badge.id);
      IF v_badge.points_reward > 0 THEN
        INSERT INTO student_points (user_id, points, reason, reference_id) VALUES (NEW.user_id, v_badge.points_reward, 'badge_earned', v_badge.id);
      END IF;
      INSERT INTO notifications (user_id, title, message, type) VALUES (NEW.user_id, 'شارة جديدة 🏆', 'تهانينا! حصلت على شارة: ' || v_badge.name, 'success');
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.check_ai_error_rate()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE v_total integer; v_errors integer; v_error_rate numeric; v_threshold numeric := 20; v_admin record; v_last_notification timestamp;
BEGIN
  IF NEW.success IS NOT FALSE THEN RETURN NEW; END IF;
  SELECT count(*), count(*) FILTER (WHERE success = false) INTO v_total, v_errors
  FROM (SELECT success FROM ai_usage_logs ORDER BY created_at DESC LIMIT 50) recent;
  IF v_total < 10 THEN RETURN NEW; END IF;
  v_error_rate := (v_errors::numeric / v_total::numeric) * 100;
  IF v_error_rate >= v_threshold THEN
    SELECT max(created_at) INTO v_last_notification FROM notifications
    WHERE type = 'warning' AND title = 'تنبيه: ارتفاع أخطاء الذكاء الاصطناعي ⚠️' AND created_at > now() - interval '1 hour';
    IF v_last_notification IS NOT NULL THEN RETURN NEW; END IF;
    FOR v_admin IN SELECT user_id FROM user_roles WHERE role = 'admin' LOOP
      INSERT INTO notifications (user_id, title, message, type)
      VALUES (v_admin.user_id, 'تنبيه: ارتفاع أخطاء الذكاء الاصطناعي ⚠️',
        'معدل أخطاء الذكاء الاصطناعي وصل إلى ' || round(v_error_rate, 1) || '% في آخر ' || v_total || ' طلب. الخطأ الأخير: ' || COALESCE(NEW.error_message, 'غير محدد'),
        'warning');
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.notify_admins_on_pending_payment()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE v_admin record; v_student_name text; v_amount text;
BEGIN
  IF NEW.status <> 'pending' THEN RETURN NEW; END IF;
  SELECT full_name INTO v_student_name FROM profiles WHERE user_id = NEW.user_id LIMIT 1;
  v_amount := NEW.amount::text || ' ' || NEW.currency;
  FOR v_admin IN SELECT user_id FROM user_roles WHERE role = 'admin' LOOP
    INSERT INTO notifications (user_id, title, message, type)
    VALUES (v_admin.user_id, 'طلب دفع جديد 💳', 'طلب دفع معلق بمبلغ ' || v_amount || ' من الطالب: ' || COALESCE(v_student_name, 'غير معروف'), 'info');
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_lesson_full_content(_lesson_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE v_lesson record; v_book jsonb; v_explanations jsonb; v_summary jsonb; v_assessments jsonb; v_resources jsonb;
BEGIN
  IF NOT public.can_access_lesson(_lesson_id) THEN RETURN jsonb_build_object('error', 'forbidden'); END IF;
  SELECT id, subject_id, unit_id, title, slug, duration, is_free, semester, video_url, content_text, content_pdf_url, sort_order INTO v_lesson FROM public.lessons WHERE id = _lesson_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'not_found'); END IF;
  SELECT to_jsonb(b) INTO v_book FROM (SELECT content, pdf_url, updated_at FROM public.lesson_book_contents WHERE lesson_id = _lesson_id LIMIT 1) b;
  IF v_book IS NULL AND (v_lesson.content_text IS NOT NULL OR v_lesson.content_pdf_url IS NOT NULL) THEN
    v_book := jsonb_build_object('content', v_lesson.content_text, 'pdf_url', v_lesson.content_pdf_url, 'source', 'legacy');
  END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.sort_order), '[]'::jsonb) INTO v_explanations FROM (SELECT id, title, content, sort_order FROM public.lesson_explanations WHERE lesson_id = _lesson_id ORDER BY sort_order) e;
  SELECT to_jsonb(s) INTO v_summary FROM (SELECT summary, key_points, study_tip FROM public.lesson_summaries WHERE lesson_id = _lesson_id LIMIT 1) s;
  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.sort_order), '[]'::jsonb) INTO v_assessments FROM (SELECT id, title, instructions, sort_order FROM public.lesson_assessments WHERE lesson_id = _lesson_id ORDER BY sort_order) a;
  WITH combined AS (
    SELECT id::text AS id, resource_type::text AS resource_type, title, url, description, sort_order, 'new' AS source FROM public.lesson_resources WHERE lesson_id = _lesson_id
    UNION ALL SELECT 'legacy-video-' || v_lesson.id::text, 'video', 'فيديو الدرس', v_lesson.video_url, NULL, 0, 'legacy' WHERE v_lesson.video_url IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.lesson_resources lr WHERE lr.lesson_id = _lesson_id AND lr.resource_type = 'video' AND lr.url = v_lesson.video_url)
    UNION ALL SELECT 'legacy-pdf-' || v_lesson.id::text, 'pdf', 'ملف PDF', v_lesson.content_pdf_url, NULL, 1, 'legacy' WHERE v_lesson.content_pdf_url IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.lesson_resources lr WHERE lr.lesson_id = _lesson_id AND lr.resource_type = 'pdf' AND lr.url = v_lesson.content_pdf_url)
    UNION ALL SELECT 'legacy-sim-' || ls.id::text, 'experiment', ls.title, ls.phet_url, ls.description, ls.sort_order + 10, 'legacy' FROM public.lesson_simulations ls WHERE ls.lesson_id = _lesson_id AND NOT EXISTS (SELECT 1 FROM public.lesson_resources lr WHERE lr.lesson_id = _lesson_id AND lr.resource_type = 'experiment' AND lr.url = ls.phet_url)
  ) SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.sort_order), '[]'::jsonb) INTO v_resources FROM combined c;
  RETURN jsonb_build_object('lesson', to_jsonb(v_lesson), 'book', v_book, 'explanations', v_explanations, 'summary', v_summary, 'assessments', v_assessments, 'resources', v_resources);
END;
$$

CREATE OR REPLACE FUNCTION public.validate_lesson_unit_subject_match()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_unit_subject uuid;
BEGIN
  IF NEW.unit_id IS NULL THEN RETURN NEW; END IF;
  SELECT subject_id INTO v_unit_subject FROM public.units WHERE id = NEW.unit_id;
  IF v_unit_subject IS NULL THEN RAISE EXCEPTION 'Unit not found' USING ERRCODE = '23514'; END IF;
  IF v_unit_subject <> NEW.subject_id THEN RAISE EXCEPTION 'Unit must belong to the same subject as the lesson' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_unit_subject_change()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NEW.subject_id <> OLD.subject_id THEN
    IF EXISTS (SELECT 1 FROM public.lessons WHERE unit_id = NEW.id) THEN
      RAISE EXCEPTION 'Cannot change unit subject while lessons are linked to this unit' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_assessment_question_link()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_assessment_lesson_id uuid; v_lesson_subject_id uuid; v_q_lesson_id uuid; v_q_subject_id uuid;
BEGIN
  SELECT la.lesson_id, l.subject_id INTO v_assessment_lesson_id, v_lesson_subject_id
  FROM public.lesson_assessments la JOIN public.lessons l ON l.id = la.lesson_id WHERE la.id = NEW.assessment_id;
  IF v_assessment_lesson_id IS NULL THEN RAISE EXCEPTION 'Assessment not found' USING ERRCODE = '23514'; END IF;
  SELECT lesson_id, subject_id INTO v_q_lesson_id, v_q_subject_id FROM public.questions WHERE id = NEW.question_id;
  IF v_q_lesson_id IS NOT NULL THEN
    IF v_q_lesson_id <> v_assessment_lesson_id THEN RAISE EXCEPTION 'Question belongs to a different lesson' USING ERRCODE = '23514'; END IF;
  ELSE
    IF v_q_subject_id IS NULL OR v_q_subject_id <> v_lesson_subject_id THEN RAISE EXCEPTION 'Question must belong to the same subject as the assessment lesson' USING ERRCODE = '23514'; END IF;
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.validate_lesson_subject_change()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NEW.subject_id IS DISTINCT FROM OLD.subject_id THEN
    IF EXISTS (SELECT 1 FROM public.lesson_assessments la JOIN public.assessment_questions aq ON aq.assessment_id = la.id JOIN public.questions q ON q.id = aq.question_id
      WHERE la.lesson_id = NEW.id AND ((q.lesson_id IS NOT NULL AND q.lesson_id = NEW.id) OR (q.lesson_id IS NULL AND q.subject_id = OLD.subject_id))) THEN
      RAISE EXCEPTION 'Cannot change lesson subject while assessments have linked questions from the current subject' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.sync_profile_grade_columns()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_exists boolean;
BEGIN
  IF NEW.grade_uuid IS DISTINCT FROM COALESCE(OLD.grade_uuid, NULL) THEN
    IF NEW.grade_uuid IS NULL THEN
      IF OLD.grade_id IS NOT NULL AND OLD.grade_uuid IS NOT NULL AND OLD.grade_id = OLD.grade_uuid::text THEN NEW.grade_id := NULL; END IF;
    ELSE NEW.grade_id := NEW.grade_uuid::text; END IF;
  END IF;
  IF NEW.grade_id IS DISTINCT FROM COALESCE(OLD.grade_id, NULL) THEN
    IF NEW.grade_id IS NULL THEN NEW.grade_uuid := NULL;
    ELSIF NEW.grade_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT EXISTS(SELECT 1 FROM public.grades WHERE id::text = NEW.grade_id) INTO v_exists;
      IF v_exists THEN NEW.grade_uuid := NEW.grade_id::uuid; END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.sync_profile_curriculum_track()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
DECLARE v_gov_id uuid; v_track_id uuid;
BEGIN
  IF NEW.governorate_id IS NULL AND NEW.governorate IS NOT NULL AND length(trim(NEW.governorate)) > 0 THEN
    SELECT id INTO v_gov_id FROM public.governorates WHERE name = trim(NEW.governorate) LIMIT 1;
    IF v_gov_id IS NOT NULL THEN NEW.governorate_id := v_gov_id; END IF;
  END IF;
  IF NEW.governorate_id IS NOT NULL THEN
    SELECT default_curriculum_track_id INTO v_track_id FROM public.governorates WHERE id = NEW.governorate_id;
    NEW.curriculum_track_id := v_track_id;
  ELSE NEW.curriculum_track_id := NULL; END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.grade_lesson_quiz(_lesson_id uuid, _answers jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_user_id uuid := auth.uid(); v_total int := 0; v_correct int := 0; v_score int := 0; v_per_question jsonb := '[]'::jsonb; v_existing_id uuid;
BEGIN
  IF v_user_id IS NULL THEN RETURN jsonb_build_object('error', 'unauthorized'); END IF;
  IF NOT public.can_access_lesson(_lesson_id) THEN RETURN jsonb_build_object('error', 'forbidden'); END IF;
  IF _answers IS NULL OR jsonb_typeof(_answers) <> 'array' THEN RETURN jsonb_build_object('error', 'invalid_payload'); END IF;
  WITH supplied AS (SELECT (elem->>'question_id')::uuid AS question_id, NULLIF(elem->>'selected_index','')::int AS selected_index FROM jsonb_array_elements(_answers) elem WHERE elem ? 'question_id'),
  graded AS (SELECT q.id AS question_id, q.correct_index, q.explanation, s.selected_index, (s.selected_index IS NOT NULL AND s.selected_index = q.correct_index) AS is_correct FROM supplied s JOIN public.questions q ON q.id = s.question_id WHERE q.lesson_id = _lesson_id)
  SELECT COUNT(*)::int, COUNT(*) FILTER (WHERE is_correct)::int,
    COALESCE(jsonb_agg(jsonb_build_object('question_id', question_id, 'is_correct', is_correct, 'explanation', explanation)), '[]'::jsonb)
  INTO v_total, v_correct, v_per_question FROM graded;
  IF v_total = 0 THEN RETURN jsonb_build_object('error', 'no_valid_questions'); END IF;
  v_score := ROUND((v_correct::numeric / v_total::numeric) * 100)::int;
  SELECT id INTO v_existing_id FROM public.user_progress WHERE user_id = v_user_id AND lesson_id = _lesson_id LIMIT 1;
  IF v_existing_id IS NOT NULL THEN
    UPDATE public.user_progress SET completed = TRUE, completed_at = COALESCE(completed_at, now()), quiz_score = GREATEST(COALESCE(quiz_score, 0), v_score), updated_at = now() WHERE id = v_existing_id;
  ELSE
    INSERT INTO public.user_progress (user_id, lesson_id, completed, completed_at, quiz_score) VALUES (v_user_id, _lesson_id, TRUE, now(), v_score);
  END IF;
  RETURN jsonb_build_object('total', v_total, 'correct', v_correct, 'score', v_score, 'per_question', v_per_question);
END;
$$

CREATE OR REPLACE FUNCTION public.get_lesson_quiz_questions(_lesson_id uuid)
RETURNS TABLE (id uuid, question_text text, options jsonb, question_type text, sort_order int)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN; END IF;
  IF NOT public.can_access_lesson(_lesson_id) THEN RETURN; END IF;
  RETURN QUERY SELECT q.id, q.question_text, q.options, q.question_type, q.sort_order
    FROM public.questions q WHERE q.lesson_id = _lesson_id ORDER BY q.sort_order;
END;
$$

CREATE OR REPLACE FUNCTION public.create_wallet_transaction(
  _user_id uuid, _type text, _direction text, _amount numeric, _currency text DEFAULT 'YER',
  _reference_type text DEFAULT NULL, _reference_id uuid DEFAULT NULL,
  _description text DEFAULT NULL, _metadata jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_caller uuid := auth.uid(); v_wallet record; v_before numeric; v_after numeric; v_tx_id uuid;
BEGIN
  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'amount must be > 0' USING ERRCODE = '22023'; END IF;
  IF _direction NOT IN ('credit','debit') THEN RAISE EXCEPTION 'invalid direction' USING ERRCODE = '22023'; END IF;
  IF _type NOT IN ('deposit','subscription_payment','refund','adjustment','manual_correction') THEN RAISE EXCEPTION 'invalid type' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_wallet FROM public.wallet_accounts WHERE user_id = _user_id AND currency = _currency FOR UPDATE;
  IF NOT FOUND THEN INSERT INTO public.wallet_accounts (user_id, currency) VALUES (_user_id, _currency) RETURNING * INTO v_wallet; END IF;
  IF v_wallet.status <> 'active' THEN RAISE EXCEPTION 'wallet is not active' USING ERRCODE = '42501'; END IF;
  v_before := v_wallet.balance;
  IF _direction = 'credit' THEN v_after := v_before + _amount;
  ELSE v_after := v_before - _amount;
    IF v_after < 0 THEN RAISE EXCEPTION 'insufficient balance' USING ERRCODE = '22023'; END IF;
  END IF;
  INSERT INTO public.wallet_transactions (wallet_account_id, user_id, type, direction, amount, currency, balance_before, balance_after, reference_type, reference_id, description, metadata, created_by)
  VALUES (v_wallet.id, _user_id, _type, _direction, _amount, _currency, v_before, v_after, _reference_type, _reference_id, _description, COALESCE(_metadata, '{}'::jsonb), v_caller) RETURNING id INTO v_tx_id;
  UPDATE public.wallet_accounts SET balance = v_after, updated_at = now() WHERE id = v_wallet.id;
  RETURN jsonb_build_object('transaction_id', v_tx_id, 'wallet_account_id', v_wallet.id, 'balance_before', v_before, 'balance_after', v_after);
END;
$$

CREATE OR REPLACE FUNCTION public.ensure_wallet_account(_user_id uuid, _currency text DEFAULT 'YER')
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id FROM public.wallet_accounts WHERE user_id = _user_id AND currency = _currency;
  IF v_id IS NULL THEN INSERT INTO public.wallet_accounts (user_id, currency) VALUES (_user_id, _currency) RETURNING id INTO v_id; END IF;
  RETURN v_id;
END;
$$

CREATE OR REPLACE FUNCTION public.write_audit_log(_action text, _target_type text, _target_id uuid, _metadata jsonb DEFAULT '{}'::jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, metadata)
  VALUES (auth.uid(), _action, _target_type, _target_id, COALESCE(_metadata, '{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$

CREATE OR REPLACE FUNCTION public.reject_payment_request(_request_id uuid, _admin_notes text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_caller uuid := auth.uid(); v_req record; v_sub record; v_now timestamptz := now(); v_sub_cancelled boolean := false;
BEGIN
  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_req FROM public.payment_requests WHERE id = _request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'payment request not found' USING ERRCODE = 'P0002'; END IF;
  IF v_req.status <> 'pending' THEN RAISE EXCEPTION 'payment request is not pending (current: %)', v_req.status USING ERRCODE = '22023'; END IF;
  UPDATE public.payment_requests SET status='rejected', admin_notes=_admin_notes, reviewed_by=v_caller, reviewed_at=v_now WHERE id = _request_id;
  IF v_req.subscription_id IS NOT NULL THEN
    SELECT * INTO v_sub FROM public.subscriptions WHERE id = v_req.subscription_id FOR UPDATE;
    IF FOUND AND v_sub.status = 'pending' THEN
      UPDATE public.subscriptions SET status='cancelled', updated_at=v_now WHERE id = v_req.subscription_id;
      v_sub_cancelled := true;
    END IF;
  END IF;
  PERFORM public.write_audit_log('payment_request.rejected', 'payment_request', v_req.id,
    jsonb_build_object('request_id', v_req.id, 'subscription_id', v_req.subscription_id, 'subscription_cancelled', v_sub_cancelled, 'reason', _admin_notes));
  RETURN jsonb_build_object('request_id', v_req.id, 'status','rejected', 'subscription_id', v_req.subscription_id, 'subscription_cancelled', v_sub_cancelled);
END;
$$

CREATE OR REPLACE FUNCTION public.approve_payment_request(_request_id uuid, _admin_notes text DEFAULT NULL::text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE v_caller uuid := auth.uid(); v_req record; v_plan record; v_sub record; v_duration_months int;
  v_now timestamptz := now(); v_expires timestamptz; v_starts timestamptz; v_flags jsonb;
  v_deposit jsonb; v_debit jsonb; v_debit_amount numeric;
BEGIN
  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_req FROM public.payment_requests WHERE id = _request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'payment request not found' USING ERRCODE = 'P0002'; END IF;
  IF v_req.status <> 'pending' THEN RAISE EXCEPTION 'payment request is not pending (current: %)', v_req.status USING ERRCODE = '22023'; END IF;
  IF v_req.amount IS NULL OR v_req.amount <= 0 THEN RAISE EXCEPTION 'invalid amount' USING ERRCODE = '22023'; END IF;
  IF v_req.payment_method_id IS NULL THEN RAISE EXCEPTION 'missing payment_method_id' USING ERRCODE = '22023'; END IF;
  IF v_req.subscription_id IS NULL THEN RAISE EXCEPTION 'missing subscription_id' USING ERRCODE = '22023'; END IF;
  IF v_req.plan_id IS NULL THEN RAISE EXCEPTION 'missing plan_id' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_plan FROM public.subscription_plans WHERE id = v_req.plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan not found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_sub FROM public.subscriptions WHERE id = v_req.subscription_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'subscription not found' USING ERRCODE = 'P0002'; END IF;
  IF v_req.currency <> v_plan.currency THEN RAISE EXCEPTION 'currency_mismatch: receipt=% plan=%', v_req.currency, v_plan.currency USING ERRCODE = '22023'; END IF;
  v_flags := COALESCE(v_req.fraud_flags, '[]'::jsonb);
  IF v_req.amount < v_plan.price THEN RAISE EXCEPTION 'insufficient_payment_amount: receipt=% plan=%', v_req.amount, v_plan.price USING ERRCODE = '22023'; END IF;
  IF v_req.amount > v_plan.price THEN
    v_flags := v_flags || jsonb_build_array(jsonb_build_object('flag','amount_surplus','expected_amount', v_plan.price,'actual_amount', v_req.amount,'surplus', v_req.amount - v_plan.price,'flagged_at', v_now));
  END IF;
  v_duration_months := COALESCE(v_plan.duration_months, 6);
  v_starts := v_now; v_expires := v_now + (v_duration_months || ' months')::interval; v_debit_amount := v_plan.price;
  UPDATE public.payment_requests SET status='approved', admin_notes=_admin_notes, reviewed_by=v_caller, reviewed_at=v_now, fraud_flags=v_flags WHERE id = _request_id;
  v_deposit := public.create_wallet_transaction(_user_id := v_req.user_id, _type := 'deposit', _direction := 'credit', _amount := v_req.amount, _currency := v_req.currency,
    _reference_type := 'payment_request', _reference_id := v_req.id, _description := 'Payment receipt approved',
    _metadata := jsonb_build_object('plan_id', v_req.plan_id, 'subscription_id', v_req.subscription_id, 'transaction_reference', v_req.transaction_reference, 'receipt_hash', v_req.receipt_hash, 'payment_method_id', v_req.payment_method_id));
  v_debit := public.create_wallet_transaction(_user_id := v_req.user_id, _type := 'subscription_payment', _direction := 'debit', _amount := v_debit_amount, _currency := v_req.currency,
    _reference_type := 'subscription', _reference_id := v_req.subscription_id, _description := 'Subscription activated from wallet deposit',
    _metadata := jsonb_build_object('payment_request_id', v_req.id, 'plan_id', v_req.plan_id, 'subscription_id', v_req.subscription_id, 'deposit_transaction_id', v_deposit->>'transaction_id', 'transaction_reference', v_req.transaction_reference, 'receipt_hash', v_req.receipt_hash));
  UPDATE public.subscriptions SET status='active', starts_at=v_starts, expires_at=v_expires, updated_at=v_now WHERE id = v_req.subscription_id;
  PERFORM public.write_audit_log('payment_request.approved', 'payment_request', v_req.id,
    jsonb_build_object('request_id', v_req.id, 'subscription_id', v_req.subscription_id, 'deposit_transaction_id', v_deposit->>'transaction_id', 'subscription_payment_transaction_id', v_debit->>'transaction_id', 'wallet_balance_after', (v_debit->>'balance_after')::numeric, 'amount', v_req.amount, 'plan_price', v_plan.price, 'currency', v_req.currency, 'fraud_flags', v_flags, 'admin_notes', _admin_notes));
  RETURN jsonb_build_object('request_id', v_req.id, 'subscription_id', v_req.subscription_id, 'deposit_transaction_id', v_deposit->>'transaction_id', 'subscription_payment_transaction_id', v_debit->>'transaction_id', 'wallet_balance_after', (v_debit->>'balance_after')::numeric, 'status','approved', 'fraud_flags', v_flags);
END;
$function$

CREATE OR REPLACE FUNCTION public.pay_subscription_from_wallet(_plan_id uuid, _grade_id uuid DEFAULT NULL, _semester integer DEFAULT NULL, _idempotency_key text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
DECLARE v_user uuid := auth.uid(); v_plan record; v_wallet record; v_now timestamptz := now(); v_expires timestamptz; v_sub_id uuid; v_tx jsonb; v_existing_tx record; v_existing_sub uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;
  IF _idempotency_key IS NOT NULL AND length(trim(_idempotency_key)) > 0 THEN
    SELECT * INTO v_existing_tx FROM public.wallet_transactions
    WHERE user_id = v_user AND type = 'subscription_payment' AND direction = 'debit' AND metadata->>'idempotency_key' = _idempotency_key LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object('subscription_id', v_existing_tx.reference_id, 'wallet_transaction_id', v_existing_tx.id, 'balance_after', v_existing_tx.balance_after, 'idempotent_replay', true);
    END IF;
  END IF;
  SELECT * INTO v_plan FROM public.subscription_plans WHERE id = _plan_id AND is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found_or_inactive' USING ERRCODE = 'P0002'; END IF;
  IF v_plan.price IS NULL OR v_plan.price <= 0 THEN RAISE EXCEPTION 'invalid_plan_price' USING ERRCODE = '22023'; END IF;
  SELECT id INTO v_existing_sub FROM public.subscriptions
  WHERE user_id = v_user AND status = 'active' AND (expires_at IS NULL OR expires_at > v_now)
    AND COALESCE(plan_id::text,'') = COALESCE(_plan_id::text,'')
    AND COALESCE(grade_id::text,'') = COALESCE(_grade_id::text,'')
    AND COALESCE(semester, -1) = COALESCE(_semester, -1) LIMIT 1;
  IF v_existing_sub IS NOT NULL THEN RAISE EXCEPTION 'active_subscription_exists' USING ERRCODE = '23505'; END IF;
  SELECT * INTO v_wallet FROM public.wallet_accounts WHERE user_id = v_user AND currency = v_plan.currency FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'wallet_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_wallet.status <> 'active' THEN RAISE EXCEPTION 'wallet_not_active' USING ERRCODE = '42501'; END IF;
  IF v_wallet.balance < v_plan.price THEN RAISE EXCEPTION 'insufficient_balance: balance=% price=%', v_wallet.balance, v_plan.price USING ERRCODE = '22023'; END IF;
  v_expires := v_now + (COALESCE(v_plan.duration_months, 6) || ' months')::interval;
  INSERT INTO public.subscriptions (user_id, plan_id, grade_id, semester, status, starts_at, expires_at)
  VALUES (v_user, _plan_id, _grade_id, _semester, 'active', v_now, v_expires) RETURNING id INTO v_sub_id;
  DECLARE v_before numeric := v_wallet.balance; v_after numeric := v_wallet.balance - v_plan.price; v_tx_id uuid;
  BEGIN
    INSERT INTO public.wallet_transactions (wallet_account_id, user_id, type, direction, amount, currency, balance_before, balance_after, reference_type, reference_id, description, metadata, created_by)
    VALUES (v_wallet.id, v_user, 'subscription_payment', 'debit', v_plan.price, v_plan.currency, v_before, v_after, 'subscription', v_sub_id, 'Subscription paid from wallet balance',
      jsonb_build_object('plan_id', _plan_id, 'subscription_id', v_sub_id, 'source', 'wallet_balance', 'idempotency_key', _idempotency_key), v_user)
    RETURNING id INTO v_tx_id;
    UPDATE public.wallet_accounts SET balance = v_after, updated_at = v_now WHERE id = v_wallet.id;
    v_tx := jsonb_build_object('transaction_id', v_tx_id, 'balance_after', v_after);
  END;
  PERFORM public.write_audit_log('subscription.paid_from_wallet', 'subscription', v_sub_id,
    jsonb_build_object('plan_id', _plan_id, 'amount', v_plan.price, 'currency', v_plan.currency, 'wallet_transaction_id', v_tx->>'transaction_id', 'balance_after', v_tx->'balance_after', 'idempotency_key', _idempotency_key));
  RETURN jsonb_build_object('subscription_id', v_sub_id, 'wallet_transaction_id', v_tx->>'transaction_id', 'balance_after', (v_tx->>'balance_after')::numeric, 'expires_at', v_expires);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_adjust_wallet(_user_id uuid, _amount numeric, _direction text, _reason text, _idempotency_key text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_wallet public.wallet_accounts; v_balance_before numeric; v_balance_after numeric; v_tx_id uuid; v_existing_tx uuid; v_metadata jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF _user_id IS NULL THEN RAISE EXCEPTION 'user_id_required'; END IF;
  IF _amount IS NULL OR _amount <= 0 THEN RAISE EXCEPTION 'amount_must_be_positive'; END IF;
  IF _direction IS NULL OR _direction NOT IN ('credit','debit') THEN RAISE EXCEPTION 'invalid_direction'; END IF;
  IF _reason IS NULL OR length(btrim(_reason)) = 0 THEN RAISE EXCEPTION 'reason_required'; END IF;
  IF _idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing_tx FROM public.wallet_transactions WHERE type = 'adjustment' AND metadata->>'idempotency_key' = _idempotency_key LIMIT 1;
    IF v_existing_tx IS NOT NULL THEN RAISE EXCEPTION 'duplicate_idempotency_key'; END IF;
  END IF;
  SELECT * INTO v_wallet FROM public.wallet_accounts WHERE user_id = _user_id AND currency = 'YER' FOR UPDATE;
  IF NOT FOUND THEN INSERT INTO public.wallet_accounts (user_id, currency, balance, status) VALUES (_user_id, 'YER', 0, 'active') RETURNING * INTO v_wallet; END IF;
  IF v_wallet.status <> 'active' THEN RAISE EXCEPTION 'wallet_not_active'; END IF;
  v_balance_before := v_wallet.balance;
  IF _direction = 'credit' THEN v_balance_after := v_balance_before + _amount;
  ELSE v_balance_after := v_balance_before - _amount;
    IF v_balance_after < 0 THEN RAISE EXCEPTION 'insufficient_balance'; END IF;
  END IF;
  v_metadata := jsonb_build_object('reason', _reason, 'adjusted_user_id', _user_id, 'admin_id', auth.uid());
  IF _idempotency_key IS NOT NULL THEN v_metadata := v_metadata || jsonb_build_object('idempotency_key', _idempotency_key); END IF;
  INSERT INTO public.wallet_transactions (wallet_account_id, user_id, type, direction, amount, currency, reference_type, reference_id, description, metadata, balance_before, balance_after, created_by)
  VALUES (v_wallet.id, _user_id, 'adjustment', _direction, _amount, 'YER', 'manual_adjustment', NULL, _reason, v_metadata, v_balance_before, v_balance_after, auth.uid())
  RETURNING id INTO v_tx_id;
  UPDATE public.wallet_accounts SET balance = v_balance_after, updated_at = now() WHERE id = v_wallet.id;
  PERFORM public.write_audit_log('wallet.adjusted', 'wallet_account', v_wallet.id,
    jsonb_build_object('adjusted_user_id', _user_id, 'amount', _amount, 'direction', _direction, 'reason', _reason, 'transaction_id', v_tx_id, 'balance_before', v_balance_before, 'balance_after', v_balance_after, 'idempotency_key', _idempotency_key));
  RETURN jsonb_build_object('wallet_account_id', v_wallet.id, 'transaction_id', v_tx_id, 'balance_before', v_balance_before, 'balance_after', v_balance_after);
END;
$$

CREATE OR REPLACE FUNCTION public.admin_refund_subscription(_subscription_id uuid, _amount numeric DEFAULT NULL, _reason text DEFAULT NULL, _cancel_subscription boolean DEFAULT true, _idempotency_key text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_admin uuid := auth.uid(); v_sub record; v_paid_tx record; v_wallet record; v_refund_amount numeric; v_partial boolean; v_new_balance numeric; v_new_tx_id uuid; v_new_status text; v_existing uuid;
BEGIN
  IF v_admin IS NULL OR NOT has_role(v_admin, 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF _subscription_id IS NULL THEN RAISE EXCEPTION 'subscription_id_required' USING ERRCODE = '22023'; END IF;
  IF _reason IS NULL OR btrim(_reason) = '' THEN RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023'; END IF;
  IF _amount IS NOT NULL AND _amount <= 0 THEN RAISE EXCEPTION 'amount_must_be_positive' USING ERRCODE = '22023'; END IF;
  IF _idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing FROM wallet_transactions WHERE metadata->>'idempotency_key' = _idempotency_key AND type IN ('refund', 'subscription_reversal') LIMIT 1;
    IF v_existing IS NOT NULL THEN RAISE EXCEPTION 'duplicate_idempotency_key' USING ERRCODE = '23505'; END IF;
  END IF;
  SELECT * INTO v_sub FROM subscriptions WHERE id = _subscription_id FOR UPDATE;
  IF v_sub.id IS NULL THEN RAISE EXCEPTION 'subscription_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_sub.status IN ('refunded', 'cancelled') THEN RAISE EXCEPTION 'subscription_already_closed' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_paid_tx FROM wallet_transactions WHERE reference_type = 'subscription' AND reference_id = _subscription_id AND type = 'subscription_payment' AND direction = 'debit' ORDER BY created_at ASC LIMIT 1;
  IF v_paid_tx.id IS NULL THEN RAISE EXCEPTION 'no_payment_transaction_found' USING ERRCODE = 'P0002'; END IF;
  IF _amount IS NULL THEN v_refund_amount := v_paid_tx.amount;
  ELSE
    IF _amount > v_paid_tx.amount THEN RAISE EXCEPTION 'amount_exceeds_paid' USING ERRCODE = '22023'; END IF;
    v_refund_amount := _amount;
  END IF;
  v_partial := v_refund_amount < v_paid_tx.amount;
  SELECT * INTO v_wallet FROM wallet_accounts WHERE user_id = v_sub.user_id AND currency = v_paid_tx.currency FOR UPDATE;
  IF v_wallet.id IS NULL THEN INSERT INTO wallet_accounts (user_id, currency, balance, status) VALUES (v_sub.user_id, v_paid_tx.currency, 0, 'active') RETURNING * INTO v_wallet; END IF;
  IF v_wallet.status <> 'active' THEN RAISE EXCEPTION 'wallet_not_active' USING ERRCODE = '22023'; END IF;
  v_new_balance := v_wallet.balance + v_refund_amount;
  INSERT INTO wallet_transactions (wallet_account_id, user_id, type, direction, amount, currency, balance_before, balance_after, reference_type, reference_id, reverses_transaction_id, description, created_by, metadata)
  VALUES (v_wallet.id, v_sub.user_id, 'refund', 'credit', v_refund_amount, v_paid_tx.currency, v_wallet.balance, v_new_balance, 'subscription', _subscription_id, v_paid_tx.id, _reason, v_admin,
    jsonb_build_object('reason', _reason, 'paid_transaction_id', v_paid_tx.id, 'paid_amount', v_paid_tx.amount, 'partial', v_partial, 'cancel_subscription', _cancel_subscription, 'idempotency_key', _idempotency_key))
  RETURNING id INTO v_new_tx_id;
  UPDATE wallet_accounts SET balance = v_new_balance, updated_at = now() WHERE id = v_wallet.id;
  v_new_status := v_sub.status;
  IF _cancel_subscription AND NOT v_partial THEN
    UPDATE subscriptions SET status = 'refunded', refunded_at = now(), refunded_by = v_admin, refund_reason = _reason, updated_at = now() WHERE id = _subscription_id;
    v_new_status := 'refunded';
  END IF;
  PERFORM write_audit_log('subscription.refunded', 'subscription', _subscription_id,
    jsonb_build_object('amount', v_refund_amount, 'currency', v_paid_tx.currency, 'partial', v_partial, 'cancel_subscription', _cancel_subscription, 'refund_transaction_id', v_new_tx_id, 'reason', _reason, 'user_id', v_sub.user_id));
  RETURN jsonb_build_object('subscription_id', _subscription_id, 'refund_transaction_id', v_new_tx_id, 'amount', v_refund_amount, 'balance_after', v_new_balance, 'partial', v_partial, 'subscription_status', v_new_status);
END;
$$

CREATE OR REPLACE FUNCTION public.get_dashboard_stats()
RETURNS TABLE(total_grades bigint, total_subjects bigint, total_lessons bigint, total_questions bigint, total_students bigint, pending_payments bigint, approved_payments bigint, rejected_payments bigint, total_revenue numeric, active_subscriptions bigint, pending_subscriptions bigint, expired_subscriptions bigint)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY SELECT * FROM extensions.dashboard_stats LIMIT 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_dashboard_stats()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  REFRESH MATERIALIZED VIEW CONCURRENTLY extensions.dashboard_stats;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_report_subscription_status(_months_back integer DEFAULT 0, _grade_id uuid DEFAULT NULL::uuid)
RETURNS TABLE(status text, sub_count bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY SELECT s.status, count(*) FROM subscriptions s
  WHERE (_months_back = 0 OR s.created_at >= date_trunc('month', now()) - (_months_back || ' months')::interval)
    AND (_grade_id IS NULL OR s.grade_id = _grade_id) GROUP BY 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_report_grade_content()
RETURNS TABLE(grade_name text, subjects_count bigint, lessons_count bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY SELECT g.name, (SELECT count(*) FROM subjects s WHERE s.grade_id = g.id), (SELECT count(*) FROM lessons l JOIN subjects s ON s.id = l.subject_id WHERE s.grade_id = g.id) FROM grades g ORDER BY g.sort_order;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_report_monthly_data(_months_back integer DEFAULT 12, _grade_id uuid DEFAULT NULL::uuid)
RETURNS TABLE(year_month text, revenue numeric, new_students bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY WITH months AS (SELECT to_char(date_trunc('month', now()) - (i || ' months')::interval, 'YYYY-MM') AS ym FROM generate_series(0, _months_back - 1) AS i),
  rev AS (SELECT to_char(created_at, 'YYYY-MM') AS ym, SUM(amount) AS total FROM payment_requests WHERE status = 'approved' AND created_at >= date_trunc('month', now()) - (_months_back || ' months')::interval GROUP BY 1),
  stu AS (SELECT to_char(created_at, 'YYYY-MM') AS ym, count(*) AS total FROM profiles WHERE created_at >= date_trunc('month', now()) - (_months_back || ' months')::interval AND (_grade_id IS NULL OR grade_id = _grade_id::text) GROUP BY 1)
  SELECT m.ym, COALESCE(r.total, 0), COALESCE(s.total, 0) FROM months m LEFT JOIN rev r ON r.ym = m.ym LEFT JOIN stu s ON s.ym = m.ym ORDER BY m.ym;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_report_governorate_data(_months_back integer DEFAULT 0, _grade_id uuid DEFAULT NULL::uuid)
RETURNS TABLE(governorate text, student_count bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY SELECT COALESCE(p.governorate, 'غير محدد'), count(*) FROM profiles p
  WHERE (_months_back = 0 OR p.created_at >= date_trunc('month', now()) - (_months_back || ' months')::interval)
    AND (_grade_id IS NULL OR p.grade_id = _grade_id::text) GROUP BY 1 ORDER BY 2 DESC;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_report_school_data(_months_back integer DEFAULT 0, _grade_id uuid DEFAULT NULL::uuid, _limit integer DEFAULT 15)
RETURNS TABLE(school_name text, governorate text, student_count bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY SELECT p.school_name, COALESCE(p.governorate, 'غير محدد'), count(*) FROM profiles p
  WHERE p.school_name IS NOT NULL AND trim(p.school_name) != ''
    AND (_months_back = 0 OR p.created_at >= date_trunc('month', now()) - (_months_back || ' months')::interval)
    AND (_grade_id IS NULL OR p.grade_id = _grade_id::text) GROUP BY 1, 2 ORDER BY 3 DESC LIMIT _limit;
END;
$function$

CREATE OR REPLACE FUNCTION public.grade_unit_practice(_unit_id uuid, _answers jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_unit record;
  v_subject record;
  v_profile record;
  v_is_admin boolean;
  v_has_sub boolean;
  v_total int := 0;
  v_correct int := 0;
  v_answered int := 0;
  v_score int := 0;
  v_per_question jsonb := '[]'::jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('error', 'unauthorized');
  END IF;

  SELECT id, subject_id, is_free INTO v_unit FROM public.units WHERE id = _unit_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  SELECT id, grade_id, curriculum_track_id INTO v_subject FROM public.subjects WHERE id = v_unit.subject_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  v_is_admin := public.has_role(v_user, 'admin'::app_role);

  IF NOT v_is_admin THEN
    SELECT grade_id, grade_uuid, curriculum_track_id INTO v_profile FROM public.profiles WHERE user_id = v_user;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'forbidden');
    END IF;

    -- Grade check
    IF NOT (
      (v_profile.grade_uuid IS NOT NULL AND v_profile.grade_uuid = v_subject.grade_id)
      OR (v_profile.grade_id IS NOT NULL AND v_profile.grade_id = v_subject.grade_id::text)
    ) THEN
      RETURN jsonb_build_object('error', 'forbidden');
    END IF;

    -- Track check
    IF v_subject.curriculum_track_id IS NOT NULL
      AND (v_profile.curriculum_track_id IS NULL OR v_profile.curriculum_track_id <> v_subject.curriculum_track_id) THEN
      RETURN jsonb_build_object('error', 'forbidden');
    END IF;

    -- Access (free or active subscription)
    IF NOT v_unit.is_free THEN
      v_has_sub := public.has_active_subscription(v_user);
      IF NOT v_has_sub THEN
        RETURN jsonb_build_object('error', 'forbidden');
      END IF;
    END IF;
  END IF;

  IF _answers IS NULL OR jsonb_typeof(_answers) <> 'array' THEN
    RETURN jsonb_build_object('error', 'invalid_payload');
  END IF;

  WITH supplied AS (
    SELECT
      (elem->>'question_id')::uuid AS question_id,
      NULLIF(elem->>'selected_index','')::int AS selected_index
    FROM jsonb_array_elements(_answers) elem
    WHERE elem ? 'question_id'
  ),
  valid_q AS (
    SELECT q.id, q.correct_index
    FROM public.questions q
    JOIN public.lessons l ON l.id = q.lesson_id
    WHERE l.unit_id = _unit_id AND l.subject_id = v_unit.subject_id
  ),
  graded AS (
    SELECT
      v.id AS question_id,
      s.selected_index,
      (s.selected_index IS NOT NULL AND s.selected_index = v.correct_index) AS is_correct
    FROM supplied s
    JOIN valid_q v ON v.id = s.question_id
  )
  SELECT
    COUNT(*)::int,
    COUNT(*) FILTER (WHERE selected_index IS NOT NULL)::int,
    COUNT(*) FILTER (WHERE is_correct)::int,
    COALESCE(jsonb_agg(jsonb_build_object('question_id', question_id, 'is_correct', is_correct)), '[]'::jsonb)
  INTO v_total, v_answered, v_correct, v_per_question
  FROM graded;

  IF v_total = 0 THEN
    RETURN jsonb_build_object('error', 'no_valid_questions');
  END IF;

  v_score := ROUND((v_correct::numeric / v_total::numeric) * 100)::int;

  RETURN jsonb_build_object(
    'total', v_total,
    'answered', v_answered,
    'correct', v_correct,
    'score', v_score,
    'per_question', v_per_question
  );
END;
$$

CREATE OR REPLACE FUNCTION public.submit_unit_practice_attempt(_unit_id uuid, _answers jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_grade jsonb;
  v_subject_id uuid;
  v_total int;
  v_answered int;
  v_correct int;
  v_score int;
  v_per_question jsonb;
  v_valid_ids uuid[];
  v_answers_clean jsonb;
  v_attempt_id uuid;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('error', 'unauthorized');
  END IF;

  -- Reuse grading (handles auth, grade/track, free/sub/admin, question filtering)
  v_grade := public.grade_unit_practice(_unit_id, _answers);

  IF v_grade ? 'error' THEN
    RETURN v_grade;
  END IF;

  SELECT subject_id INTO v_subject_id FROM public.units WHERE id = _unit_id;
  IF v_subject_id IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  v_total      := COALESCE((v_grade->>'total')::int, 0);
  v_answered   := COALESCE((v_grade->>'answered')::int, 0);
  v_correct    := COALESCE((v_grade->>'correct')::int, 0);
  v_score      := COALESCE((v_grade->>'score')::int, 0);
  v_per_question := COALESCE(v_grade->'per_question', '[]'::jsonb);

  -- Whitelist of valid question_ids (the ones that were graded)
  SELECT COALESCE(array_agg((pq->>'question_id')::uuid), ARRAY[]::uuid[])
  INTO v_valid_ids
  FROM jsonb_array_elements(v_per_question) pq;

  -- Clean answers: only question_id + selected_index, and only ids in valid set
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'question_id', (elem->>'question_id')::uuid,
            'selected_index', NULLIF(elem->>'selected_index','')::int
         )), '[]'::jsonb)
  INTO v_answers_clean
  FROM jsonb_array_elements(_answers) elem
  WHERE elem ? 'question_id'
    AND (elem->>'question_id')::uuid = ANY(v_valid_ids);

  INSERT INTO public.unit_practice_attempts (
    user_id, unit_id, subject_id, total, answered, correct, score, answers, per_question
  ) VALUES (
    v_user, _unit_id, v_subject_id, v_total, v_answered, v_correct, v_score, v_answers_clean, v_per_question
  )
  RETURNING id INTO v_attempt_id;

  RETURN jsonb_build_object(
    'attempt_id', v_attempt_id,
    'total', v_total,
    'answered', v_answered,
    'correct', v_correct,
    'score', v_score,
    'per_question', v_per_question
  );
END;
$$

