CREATE OR REPLACE FUNCTION public.start_exam_session(_template_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_tpl public.exam_templates;
  v_session_id uuid;
  v_total_q integer := 0;
  v_total_pts numeric := 0;
  v_expires timestamptz;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_tpl FROM public.exam_templates WHERE id = _template_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'template_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_tpl.is_active IS NOT TRUE THEN RAISE EXCEPTION 'template_inactive' USING ERRCODE = '42501'; END IF;

  SELECT COUNT(*), COALESCE(SUM(points), 0) INTO v_total_q, v_total_pts
  FROM public.exam_template_questions WHERE template_id = _template_id;

  IF v_total_q = 0 THEN RAISE EXCEPTION 'template_has_no_questions' USING ERRCODE = '22023'; END IF;

  IF v_tpl.duration_seconds IS NOT NULL THEN
    v_expires := now() + make_interval(secs => v_tpl.duration_seconds);
  END IF;

  INSERT INTO public.exam_sessions (user_id, template_id, mode, status, expires_at, total_questions, total_points)
  VALUES (v_user, _template_id, v_tpl.mode, 'in_progress', v_expires, v_total_q, v_total_pts)
  RETURNING id INTO v_session_id;

  INSERT INTO public.exam_session_answers (session_id, question_id)
  SELECT v_session_id, tq.question_id
  FROM public.exam_template_questions tq
  WHERE tq.template_id = _template_id
  ORDER BY tq.sort_order;

  RETURN v_session_id;
END;
$$

CREATE OR REPLACE FUNCTION public.answer_exam_question(_session_id uuid, _question_id uuid, _selected_index integer)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_session public.exam_sessions;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;
  IF _selected_index IS NOT NULL AND _selected_index < 0 THEN
    RAISE EXCEPTION 'invalid_selected_index' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_session FROM public.exam_sessions WHERE id = _session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_session.user_id <> v_user THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF v_session.status <> 'in_progress' THEN RAISE EXCEPTION 'session_not_in_progress' USING ERRCODE = '22023'; END IF;

  IF v_session.expires_at IS NOT NULL AND v_session.expires_at < now() THEN
    UPDATE public.exam_sessions SET status = 'expired', updated_at = now() WHERE id = _session_id;
    RAISE EXCEPTION 'session_expired' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.exam_session_answers WHERE session_id = _session_id AND question_id = _question_id) THEN
    RAISE EXCEPTION 'question_not_in_session' USING ERRCODE = '22023';
  END IF;

  UPDATE public.exam_session_answers
  SET selected_index = _selected_index,
      answered_at = now(),
      updated_at = now()
  WHERE session_id = _session_id AND question_id = _question_id;

  RETURN jsonb_build_object('ok', true);
END;
$$

CREATE OR REPLACE FUNCTION public.get_exam_session_state(_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_is_admin boolean;
  v_session public.exam_sessions;
  v_template jsonb;
  v_answers jsonb;
  v_questions jsonb;
  v_reveal boolean;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;
  v_is_admin := public.has_role(v_user, 'admin'::app_role);

  SELECT * INTO v_session FROM public.exam_sessions WHERE id = _session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_session.user_id <> v_user AND NOT v_is_admin THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_reveal := (v_session.status <> 'in_progress');

  SELECT to_jsonb(t) - 'created_by' INTO v_template
  FROM public.exam_templates t WHERE t.id = v_session.template_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'question_id', a.question_id,
    'selected_index', a.selected_index,
    'answered_at', a.answered_at,
    'is_correct', CASE WHEN v_reveal THEN a.is_correct ELSE NULL END,
    'points_awarded', CASE WHEN v_reveal THEN a.points_awarded ELSE NULL END
  ) ORDER BY a.created_at), '[]'::jsonb)
  INTO v_answers
  FROM public.exam_session_answers a
  WHERE a.session_id = _session_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', q.id,
    'question_text', q.question_text,
    'options', q.options,
    'question_type', q.question_type,
    'sort_order', tq.sort_order,
    'points', tq.points,
    'correct_index', CASE WHEN v_reveal THEN q.correct_index ELSE NULL END,
    'explanation', CASE WHEN v_reveal THEN q.explanation ELSE NULL END
  ) ORDER BY tq.sort_order), '[]'::jsonb)
  INTO v_questions
  FROM public.exam_template_questions tq
  JOIN public.questions q ON q.id = tq.question_id
  WHERE tq.template_id = v_session.template_id;

  RETURN jsonb_build_object(
    'session', to_jsonb(v_session) - 'result_json' || jsonb_build_object('result_json', CASE WHEN v_reveal THEN v_session.result_json ELSE NULL END),
    'template', v_template,
    'questions', v_questions,
    'answers', v_answers,
    'reveal', v_reveal
  );
END;
$$

CREATE OR REPLACE FUNCTION public.check_lesson_question(_question_id uuid, _selected_index integer)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_q record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;
  SELECT id, lesson_id, correct_index, explanation INTO v_q FROM public.questions WHERE id = _question_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'question_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_q.lesson_id IS NULL OR NOT public.can_access_lesson(v_q.lesson_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object(
    'question_id', v_q.id,
    'is_correct', (_selected_index IS NOT NULL AND _selected_index = v_q.correct_index),
    'correct_index', v_q.correct_index,
    'explanation', v_q.explanation
  );
END;
$$

CREATE OR REPLACE FUNCTION public.validate_payment_method_type()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.type NOT IN ('bank','exchange','ewallet','network_transfer','kuraimi_transfer','hasib_point') THEN
    RAISE EXCEPTION 'type must be bank, exchange, ewallet, network_transfer, kuraimi_transfer, or hasib_point';
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.sync_profile_curriculum_track()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_gov_id uuid;
  v_default uuid;
  v_allowed boolean;
BEGIN
  -- استنتج governorate_id من النص القديم إن لزم
  IF NEW.governorate_id IS NULL AND NEW.governorate IS NOT NULL AND length(trim(NEW.governorate)) > 0 THEN
    SELECT id INTO v_gov_id FROM public.governorates WHERE name = trim(NEW.governorate) LIMIT 1;
    IF v_gov_id IS NOT NULL THEN NEW.governorate_id := v_gov_id; END IF;
  END IF;

  -- لا governorate → لا نفعل شيئًا خطيرًا
  IF NEW.governorate_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.curriculum_track_id IS NOT NULL THEN
    -- احترم اختيار التطبيق لكن تحقق أنه مسموح للمحافظة
    SELECT EXISTS (
      SELECT 1 FROM public.governorate_curriculum_map
      WHERE governorate_id = NEW.governorate_id
        AND curriculum_track_id = NEW.curriculum_track_id
    ) INTO v_allowed;

    -- fallback: السماح إن كان هو الـ default للمحافظة (حماية بيانات قديمة قبل ملء الخريطة)
    IF NOT v_allowed THEN
      SELECT default_curriculum_track_id INTO v_default
      FROM public.governorates WHERE id = NEW.governorate_id;
      IF v_default IS NOT NULL AND v_default = NEW.curriculum_track_id THEN
        v_allowed := true;
      END IF;
    END IF;

    IF NOT v_allowed THEN
      RAISE EXCEPTION 'curriculum_track_not_allowed_for_governorate'
        USING ERRCODE = '22023',
              HINT = 'اختر منهجاً مسموحاً لهذه المحافظة من governorate_curriculum_map';
    END IF;
  ELSE
    -- فارغ → املأ من default المحافظة
    SELECT default_curriculum_track_id INTO v_default
    FROM public.governorates WHERE id = NEW.governorate_id;
    NEW.curriculum_track_id := v_default;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_user_total_points(_user_id uuid)
RETURNS integer
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() <> _user_id
     AND NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE(
    (SELECT SUM(points)::integer FROM public.student_points WHERE user_id = _user_id),
    0
  );
END;
$$

CREATE OR REPLACE FUNCTION public.ensure_wallet_account(_user_id uuid, _currency text DEFAULT 'YER')
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL
     AND auth.uid() <> _user_id
     AND NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_id
  FROM public.wallet_accounts
  WHERE user_id = _user_id AND currency = _currency;

  IF v_id IS NULL THEN
    INSERT INTO public.wallet_accounts (user_id, currency)
    VALUES (_user_id, _currency)
    RETURNING id INTO v_id;
  END IF;

  RETURN v_id;
END;
$$

CREATE OR REPLACE FUNCTION public.has_active_subscription(_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  IF auth.uid() <> _user_id AND NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.subscriptions
    WHERE user_id = _user_id AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
  );
END;
$$

CREATE OR REPLACE FUNCTION public.get_user_total_points(_user_id uuid)
RETURNS integer
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;
  IF auth.uid() <> _user_id AND NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE((SELECT SUM(points)::integer FROM public.student_points WHERE user_id = _user_id), 0);
END;
$$

CREATE OR REPLACE FUNCTION public.ensure_wallet_account(_user_id uuid, _currency text DEFAULT 'YER')
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL AND auth.uid() <> _user_id AND NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT id INTO v_id FROM public.wallet_accounts WHERE user_id = _user_id AND currency = _currency;
  IF v_id IS NULL THEN
    INSERT INTO public.wallet_accounts (user_id, currency) VALUES (_user_id, _currency) RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$

CREATE OR REPLACE FUNCTION public.start_exam_session(_template_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_tpl public.exam_templates;
  v_subject_id uuid;
  v_subject record;
  v_profile record;
  v_session_id uuid;
  v_total_q integer := 0;
  v_total_pts numeric := 0;
  v_expires timestamptz;
  v_is_admin boolean;
  v_is_free boolean := false;
  v_lesson_is_free boolean;
  v_lesson_unit_id uuid;
  v_unit_is_free boolean;
  v_mode text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_tpl FROM public.exam_templates WHERE id = _template_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'template_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_tpl.is_active IS NOT TRUE THEN
    RAISE EXCEPTION 'template_inactive' USING ERRCODE = '42501';
  END IF;

  v_subject_id := v_tpl.subject_id;
  IF v_subject_id IS NULL AND v_tpl.unit_id IS NOT NULL THEN
    SELECT u.subject_id INTO v_subject_id FROM public.units u WHERE u.id = v_tpl.unit_id;
  END IF;
  IF v_subject_id IS NULL AND v_tpl.lesson_id IS NOT NULL THEN
    SELECT l.subject_id INTO v_subject_id FROM public.lessons l WHERE l.id = v_tpl.lesson_id;
  END IF;
  IF v_subject_id IS NULL THEN
    RAISE EXCEPTION 'template_scope_missing' USING ERRCODE = '42501';
  END IF;

  SELECT s.id, s.grade_id, s.curriculum_track_id
  INTO v_subject
  FROM public.subjects s
  WHERE s.id = v_subject_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'template_scope_missing' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.has_role(v_user, 'admin'::app_role);

  IF NOT v_is_admin THEN
    SELECT p.grade_id, p.grade_uuid, p.curriculum_track_id
    INTO v_profile
    FROM public.profiles p
    WHERE p.user_id = v_user;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'grade_mismatch' USING ERRCODE = '42501';
    END IF;

    IF NOT public.user_can_access_subject_curriculum(v_subject_id) THEN
      RAISE EXCEPTION 'curriculum_mismatch' USING ERRCODE = '42501';
    END IF;

    IF NOT (
      (v_profile.grade_uuid IS NOT NULL AND v_profile.grade_uuid = v_subject.grade_id)
      OR (v_profile.grade_id IS NOT NULL AND v_profile.grade_id = v_subject.grade_id::text)
    ) THEN
      RAISE EXCEPTION 'grade_mismatch' USING ERRCODE = '42501';
    END IF;

    v_mode := v_tpl.mode::text;
    IF v_mode IS NULL OR v_mode NOT IN ('training', 'strict', 'ministry') THEN
      v_mode := 'strict';
    END IF;

    IF v_tpl.lesson_id IS NOT NULL THEN
      SELECT l.is_free, l.unit_id
      INTO v_lesson_is_free, v_lesson_unit_id
      FROM public.lessons l
      WHERE l.id = v_tpl.lesson_id;
      IF FOUND THEN
        IF v_lesson_is_free OR public.is_first_lesson_in_subject(v_tpl.lesson_id) THEN
          v_is_free := true;
        ELSIF v_lesson_unit_id IS NOT NULL THEN
          SELECT u.is_free INTO v_unit_is_free FROM public.units u WHERE u.id = v_lesson_unit_id;
          IF FOUND AND v_unit_is_free THEN
            v_is_free := true;
          END IF;
        END IF;
      END IF;
    ELSIF v_tpl.unit_id IS NOT NULL THEN
      SELECT u.is_free INTO v_unit_is_free FROM public.units u WHERE u.id = v_tpl.unit_id;
      IF FOUND AND v_unit_is_free THEN
        v_is_free := true;
      END IF;
    END IF;

    IF v_mode IN ('strict', 'ministry') THEN
      IF NOT public.has_active_subscription(v_user) THEN
        RAISE EXCEPTION 'subscription_required' USING ERRCODE = '42501';
      END IF;
    ELSIF v_mode = 'training' THEN
      IF NOT v_is_free AND NOT public.has_active_subscription(v_user) THEN
        RAISE EXCEPTION 'subscription_required' USING ERRCODE = '42501';
      END IF;
    ELSE
      IF NOT public.has_active_subscription(v_user) THEN
        RAISE EXCEPTION 'subscription_required' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  SELECT COUNT(*), COALESCE(SUM(points), 0)
  INTO v_total_q, v_total_pts
  FROM public.exam_template_questions
  WHERE template_id = _template_id;

  IF v_total_q = 0 THEN
    RAISE EXCEPTION 'template_has_no_questions' USING ERRCODE = '22023';
  END IF;

  IF v_tpl.duration_seconds IS NOT NULL THEN
    v_expires := now() + make_interval(secs => v_tpl.duration_seconds);
  END IF;

  INSERT INTO public.exam_sessions (
    user_id, template_id, mode, status, expires_at, total_questions, total_points
  )
  VALUES (
    v_user, _template_id, v_tpl.mode, 'in_progress', v_expires, v_total_q, v_total_pts
  )
  RETURNING id INTO v_session_id;

  INSERT INTO public.exam_session_answers (session_id, question_id)
  SELECT v_session_id, tq.question_id
  FROM public.exam_template_questions tq
  WHERE tq.template_id = _template_id
  ORDER BY tq.sort_order;

  RETURN v_session_id;
END;
$$

CREATE OR REPLACE FUNCTION public.start_exam_session(_template_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_tpl public.exam_templates;
  v_subject_id uuid;
  v_subject record;
  v_profile record;
  v_session_id uuid;
  v_total_q integer := 0;
  v_total_pts numeric := 0;
  v_expires timestamptz;
  v_is_admin boolean;
  v_is_free boolean := false;
  v_lesson_is_free boolean;
  v_lesson_unit_id uuid;
  v_unit_is_free boolean;
  v_mode text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_tpl FROM public.exam_templates WHERE id = _template_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'template_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_tpl.is_active IS NOT TRUE THEN
    RAISE EXCEPTION 'template_inactive' USING ERRCODE = '42501';
  END IF;

  v_subject_id := v_tpl.subject_id;
  IF v_subject_id IS NULL AND v_tpl.unit_id IS NOT NULL THEN
    SELECT u.subject_id INTO v_subject_id FROM public.units u WHERE u.id = v_tpl.unit_id;
  END IF;
  IF v_subject_id IS NULL AND v_tpl.lesson_id IS NOT NULL THEN
    SELECT l.subject_id INTO v_subject_id FROM public.lessons l WHERE l.id = v_tpl.lesson_id;
  END IF;
  IF v_subject_id IS NULL THEN
    RAISE EXCEPTION 'template_scope_missing' USING ERRCODE = '42501';
  END IF;

  SELECT s.id, s.grade_id, s.curriculum_track_id
  INTO v_subject
  FROM public.subjects s
  WHERE s.id = v_subject_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'template_scope_missing' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.has_role(v_user, 'admin'::app_role);

  IF NOT v_is_admin THEN
    SELECT p.grade_id, p.grade_uuid, p.curriculum_track_id
    INTO v_profile
    FROM public.profiles p
    WHERE p.user_id = v_user;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'grade_mismatch' USING ERRCODE = '42501';
    END IF;

    IF NOT public.user_can_access_subject_curriculum(v_subject_id) THEN
      RAISE EXCEPTION 'curriculum_mismatch' USING ERRCODE = '42501';
    END IF;

    IF NOT (
      (v_profile.grade_uuid IS NOT NULL AND v_profile.grade_uuid = v_subject.grade_id)
      OR (v_profile.grade_id IS NOT NULL AND v_profile.grade_id = v_subject.grade_id::text)
    ) THEN
      RAISE EXCEPTION 'grade_mismatch' USING ERRCODE = '42501';
    END IF;

    v_mode := v_tpl.mode::text;
    IF v_mode IS NULL OR v_mode NOT IN ('training', 'strict', 'ministry') THEN
      v_mode := 'strict';
    END IF;

    IF v_tpl.lesson_id IS NOT NULL THEN
      SELECT l.is_free, l.unit_id
      INTO v_lesson_is_free, v_lesson_unit_id
      FROM public.lessons l
      WHERE l.id = v_tpl.lesson_id;
      IF FOUND THEN
        IF v_lesson_is_free OR public.is_first_lesson_in_subject(v_tpl.lesson_id) THEN
          v_is_free := true;
        ELSIF v_lesson_unit_id IS NOT NULL THEN
          SELECT u.is_free INTO v_unit_is_free FROM public.units u WHERE u.id = v_lesson_unit_id;
          IF FOUND AND v_unit_is_free THEN
            v_is_free := true;
          END IF;
        END IF;
      END IF;
    ELSIF v_tpl.unit_id IS NOT NULL THEN
      SELECT u.is_free INTO v_unit_is_free FROM public.units u WHERE u.id = v_tpl.unit_id;
      IF FOUND AND v_unit_is_free THEN
        v_is_free := true;
      END IF;
    END IF;

    IF v_mode IN ('strict', 'ministry') THEN
      IF NOT public.has_active_subscription(v_user) THEN
        RAISE EXCEPTION 'subscription_required' USING ERRCODE = '42501';
      END IF;
    ELSIF v_mode = 'training' THEN
      IF NOT v_is_free AND NOT public.has_active_subscription(v_user) THEN
        RAISE EXCEPTION 'subscription_required' USING ERRCODE = '42501';
      END IF;
    ELSE
      IF NOT public.has_active_subscription(v_user) THEN
        RAISE EXCEPTION 'subscription_required' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  SELECT COUNT(*), COALESCE(SUM(points), 0)
  INTO v_total_q, v_total_pts
  FROM public.exam_template_questions
  WHERE template_id = _template_id;

  IF v_total_q = 0 THEN
    RAISE EXCEPTION 'template_has_no_questions' USING ERRCODE = '22023';
  END IF;

  IF v_tpl.duration_seconds IS NOT NULL THEN
    v_expires := now() + make_interval(secs => v_tpl.duration_seconds);
  END IF;

  INSERT INTO public.exam_sessions (
    user_id, template_id, mode, status, expires_at, total_questions, total_points
  )
  VALUES (
    v_user, _template_id, v_tpl.mode, 'in_progress', v_expires, v_total_q, v_total_pts
  )
  RETURNING id INTO v_session_id;

  INSERT INTO public.exam_session_answers (session_id, question_id)
  SELECT v_session_id, tq.question_id
  FROM public.exam_template_questions tq
  WHERE tq.template_id = _template_id
  ORDER BY tq.sort_order;

  RETURN v_session_id;
END;
$$

policies.statement:
CREATE POLICY "Authenticated can read questions of active templates"
  ON public.exam_template_questions FOR SELECT TO authenticated
  USING (
    public.is_content_staff(auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.exam_templates t
      WHERE t.id = template_id AND t.is_active = true
    )
  )

CREATE POLICY "Content staff manage import jobs"
  ON public.import_jobs FOR ALL TO authenticated
  USING (public.is_content_staff(auth.uid()))
  WITH CHECK (
    public.is_content_staff(auth.uid())
    AND (
      public.is_full_admin(auth.uid())
      OR import_type <> 'config'
    )
  )

functions.statement:
CREATE OR REPLACE FUNCTION public.create_wallet_topup_request(
  p_payment_method_id uuid,
  p_amount numeric,
  p_receipt_path text,
  p_currency text DEFAULT 'YER',
  p_sender_name text DEFAULT NULL,
  p_sender_account text DEFAULT NULL,
  p_transaction_reference text DEFAULT NULL,
  p_payment_date date DEFAULT NULL,
  p_receipt_hash text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_wallet_id uuid;
  v_method record;
  v_request_id uuid;
  v_expected_prefix text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF public.has_role(v_user, 'content_manager'::public.app_role)
     OR public.has_role(v_user, 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'staff_accounts_cannot_create_wallet_topup_requests' USING ERRCODE = '42501';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount_must_be_positive' USING ERRCODE = '22023';
  END IF;

  IF p_payment_method_id IS NULL THEN
    RAISE EXCEPTION 'payment_method_required' USING ERRCODE = '22023';
  END IF;

  IF p_receipt_path IS NULL OR length(trim(p_receipt_path)) = 0 THEN
    RAISE EXCEPTION 'receipt_path_required' USING ERRCODE = '22023';
  END IF;

  v_expected_prefix := v_user::text || '/wallet-topups/';
  IF p_receipt_path NOT LIKE v_expected_prefix || '%' THEN
    RAISE EXCEPTION 'invalid_receipt_path' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_method
  FROM public.payment_methods
  WHERE id = p_payment_method_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_method_not_found_or_inactive' USING ERRCODE = 'P0002';
  END IF;

  v_wallet_id := public.ensure_wallet_account(v_user, COALESCE(NULLIF(trim(p_currency), ''), 'YER'));

  INSERT INTO public.wallet_topup_requests (
    user_id,
    wallet_account_id,
    payment_method_id,
    amount,
    currency,
    receipt_path,
    sender_name,
    sender_account,
    transaction_reference,
    payment_date,
    receipt_hash,
    status
  )
  VALUES (
    v_user,
    v_wallet_id,
    p_payment_method_id,
    p_amount,
    COALESCE(NULLIF(trim(p_currency), ''), 'YER'),
    trim(p_receipt_path),
    NULLIF(trim(p_sender_name), ''),
    NULLIF(trim(p_sender_account), ''),
    NULLIF(trim(p_transaction_reference), ''),
    p_payment_date,
    NULLIF(trim(p_receipt_hash), ''),
    'submitted'
  )
  RETURNING id INTO v_request_id;

  RETURN jsonb_build_object(
    'request_id', v_request_id,
    'wallet_account_id', v_wallet_id,
    'status', 'submitted'
  );
END;
$$

CREATE OR REPLACE FUNCTION public.approve_wallet_topup_request(
  p_request_id uuid,
  p_admin_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_req record;
  v_deposit jsonb;
  v_existing_tx uuid;
BEGIN
  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_req
  FROM public.wallet_topup_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'wallet_topup_request_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_req.status = 'credited' THEN
    RETURN jsonb_build_object(
      'request_id', v_req.id,
      'status', v_req.status,
      'wallet_account_id', v_req.wallet_account_id,
      'credited_transaction_id', v_req.credited_transaction_id,
      'already_processed', true
    );
  END IF;

  IF v_req.status = 'rejected' THEN
    RAISE EXCEPTION 'wallet_topup_request_already_rejected' USING ERRCODE = '22023';
  END IF;

  IF v_req.status NOT IN ('submitted', 'under_review') THEN
    RAISE EXCEPTION 'wallet_topup_request_not_reviewable (current: %)', v_req.status USING ERRCODE = '22023';
  END IF;

  IF v_req.wallet_account_id IS NULL THEN
    v_req.wallet_account_id := public.ensure_wallet_account(v_req.user_id, v_req.currency);
    UPDATE public.wallet_topup_requests
    SET wallet_account_id = v_req.wallet_account_id, updated_at = now()
    WHERE id = v_req.id;
  END IF;

  v_deposit := public.create_wallet_transaction(
    _user_id := v_req.user_id,
    _type := 'deposit',
    _direction := 'credit',
    _amount := v_req.amount,
    _currency := v_req.currency,
    _reference_type := 'wallet_topup',
    _reference_id := v_req.id,
    _description := 'Wallet top-up approved',
    _metadata := jsonb_build_object(
      'wallet_topup_request_id', v_req.id,
      'payment_method_id', v_req.payment_method_id,
      'receipt_path', v_req.receipt_path,
      'receipt_hash', v_req.receipt_hash,
      'transaction_reference', v_req.transaction_reference,
      'idempotency_key', 'wallet-topup-approval:' || v_req.id::text
    )
  );

  v_existing_tx := (v_deposit->>'transaction_id')::uuid;

  UPDATE public.wallet_topup_requests
  SET
    status = 'credited',
    reviewed_by = v_caller,
    reviewed_at = now(),
    admin_notes = COALESCE(p_admin_notes, admin_notes),
    rejection_reason = NULL,
    credited_transaction_id = v_existing_tx,
    updated_at = now()
  WHERE id = v_req.id;

  PERFORM public.write_audit_log(
    'wallet_topup.approved',
    'wallet_topup_request',
    v_req.id,
    jsonb_build_object(
      'request_id', v_req.id,
      'user_id', v_req.user_id,
      'amount', v_req.amount,
      'currency', v_req.currency,
      'deposit_transaction_id', v_existing_tx,
      'wallet_balance_after', (v_deposit->>'balance_after')::numeric,
      'admin_notes', p_admin_notes
    )
  );

  RETURN jsonb_build_object(
    'request_id', v_req.id,
    'status', 'credited',
    'wallet_account_id', v_req.wallet_account_id,
    'credited_transaction_id', v_existing_tx,
    'wallet_balance_after', (v_deposit->>'balance_after')::numeric,
    'already_processed', false
  );
END;
$$

CREATE OR REPLACE FUNCTION public.reject_wallet_topup_request(
  p_request_id uuid,
  p_rejection_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_req record;
BEGIN
  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_rejection_reason IS NULL OR length(trim(p_rejection_reason)) = 0 THEN
    RAISE EXCEPTION 'rejection_reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_req
  FROM public.wallet_topup_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'wallet_topup_request_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_req.status = 'credited' THEN
    RAISE EXCEPTION 'credited_request_cannot_be_rejected' USING ERRCODE = '22023';
  END IF;

  IF v_req.status = 'rejected' THEN
    RETURN jsonb_build_object(
      'request_id', v_req.id,
      'status', v_req.status,
      'already_processed', true
    );
  END IF;

  IF v_req.status NOT IN ('submitted', 'under_review') THEN
    RAISE EXCEPTION 'wallet_topup_request_not_reviewable (current: %)', v_req.status USING ERRCODE = '22023';
  END IF;

  UPDATE public.wallet_topup_requests
  SET
    status = 'rejected',
    rejection_reason = trim(p_rejection_reason),
    reviewed_by = v_caller,
    reviewed_at = now(),
    updated_at = now()
  WHERE id = v_req.id;

  PERFORM public.write_audit_log(
    'wallet_topup.rejected',
    'wallet_topup_request',
    v_req.id,
    jsonb_build_object(
      'request_id', v_req.id,
      'user_id', v_req.user_id,
      'rejection_reason', trim(p_rejection_reason)
    )
  );

  RETURN jsonb_build_object(
    'request_id', v_req.id,
    'status', 'rejected',
    'already_processed', false
  );
END;
$$

